driver=r'''const fs=require('node:fs'),cp=require('node:child_process'),crypto=require('node:crypto');const dir=process.argv[2],base=JSON.parse(fs.readFileSync(process.argv[3])),ts=require(process.argv[4]);const cases=JSON.parse(fs.readFileSync(dir+'/cases.json'));const sha=t=>crypto.createHash('sha256').update(t).digest('hex');const results=[];
for(const [i,c]of cases.entries()){const file='main.'+c.language,sf=ts.createSourceFile(file,c.source,ts.ScriptTarget.ES2022,true,c.language==='js'?ts.ScriptKind.JS:ts.ScriptKind.TS);let selected;const visit=n=>{if(ts.isFunctionDeclaration(n)&&n.name.text==='helper')selected=n;ts.forEachChild(n,visit)};visit(sf);const request=structuredClone(base);delete request.contents['main.ts'];request.contents[file]=c.source;const config=JSON.parse(request.contents['tsconfig.json']);config.files=[file];Object.assign(config.compilerOptions,{strict:true,allowJs:true,checkJs:true,allowUnreachableCode:false,allowUnusedLabels:false,noUnusedLocals:true,noUnusedParameters:true,noFallthroughCasesInSwitch:true});request.contents['tsconfig.json']=JSON.stringify(config);const at=p=>Buffer.byteLength(c.source.slice(0,p));Object.assign(request.intent,{path:file,startByte:at(selected.getStart(sf)),endByte:at(selected.end),nameStartByte:at(selected.name.getStart(sf)),nameEndByte:at(selected.name.end),keepDefinition:c.keep});request.sourceBindings=Object.fromEntries(Object.entries(request.contents).map(([p,t])=>[p,sha(t)]));const data=JSON.stringify(request);fs.writeFileSync(dir+'/request-'+i+'.json',data);const r=cp.spawnSync(process.execPath,[dir+'/worker.cjs',sha(data)],{cwd:dir,input:data,maxBuffer:16e6});fs.writeFileSync(dir+'/stdout-'+i+'.json',r.stdout);fs.writeFileSync(dir+'/stderr-'+i+'.log',r.stderr);results.push({case:i,language:c.language,exitCode:r.status,error:r.stderr.toString()});}const result={cases:results,allChecksPassed:results.every(r=>r.exitCode===0),nativeAdmission:false,snapshotIdsSynthetic:true,analyzedCodeExecuted:false,diagnosticOnlyWorkerPatch:true};fs.writeFileSync(dir+'/result.json',JSON.stringify(result,null,2)+'\n');process.stdout.write(JSON.stringify(result)+'\n');'''
